import React, { useState, useEffect } from "react";
import axios from "axios";

const CreatePeriod = () => {
    const [name, setName] = useState("");
    const [startTime, setStartTime] = useState("");
    const [endTime, setEndTime] = useState("");
    const [dayOfWeek, setDayOfWeek] = useState(""); // ✅ День недели
    const [room, setRoom] = useState(""); // ✅ Кабинет
    const [periods, setPeriods] = useState([]);
    const [rooms, setRooms] = useState([]);

    // ✅ Дни недели (локальные)
    const weekDays = [
        { id: 1, name: "Понедельник" },
        { id: 2, name: "Вторник" },
        { id: 3, name: "Среда" },
        { id: 4, name: "Четверг" },
        { id: 5, name: "Пятница" },
        { id: 6, name: "Суббота" },
        { id: 7, name: "Воскресенье" }
    ];

    // ✅ Загружаем список времени пар и кабинетов
    useEffect(() => {
        const fetchData = async () => {
            try {
                const token = localStorage.getItem("token");
                const [periodsResponse, roomsResponse] = await Promise.all([
                    axios.get("/api/periods", { headers: { Authorization: `Bearer ${token}` } }),
                    axios.get("/api/rooms", { headers: { Authorization: `Bearer ${token}` } })
                ]);
                setPeriods(periodsResponse.data);
                setRooms(roomsResponse.data);
            } catch (error) {
                console.error("Ошибка загрузки данных:", error);
            }
        };

        fetchData();
    }, []);

    // ✅ Функция добавления нового времени пары
    const handleCreatePeriod = async (e) => {
        e.preventDefault();
        try {
            const token = localStorage.getItem("token");
            const response = await axios.post("/api/periods", { name, startTime, endTime, dayOfWeek, room }, {
                headers: { Authorization: `Bearer ${token}` }
            });

            setPeriods([...periods, response.data]); // Добавляем в список
            setName("");
            setStartTime("");
            setEndTime("");
            setDayOfWeek("");
            setRoom("");
        } catch (error) {
            console.error("Ошибка при добавлении времени пары", error);
        }
    };

    return (
        <div>
            <h2>Добавить время пары</h2>
            <form onSubmit={handleCreatePeriod}>
                <input type="text" placeholder="Название (Напр. 1 пара)" value={name} onChange={(e) => setName(e.target.value)} required />
                <input type="time" value={startTime} onChange={(e) => setStartTime(e.target.value)} required />
                <input type="time" value={endTime} onChange={(e) => setEndTime(e.target.value)} required />

                {/* ✅ Выбор дня недели */}
                <select value={dayOfWeek} onChange={(e) => setDayOfWeek(e.target.value)} required>
                    <option value="">Выберите день недели</option>
                    {weekDays.map(day => (
                        <option key={day.id} value={day.id}>{day.name}</option>
                    ))}
                </select>

                {/* ✅ Выбор кабинета */}
                <select value={room} onChange={(e) => setRoom(e.target.value)} required>
                    <option value="">Выберите кабинет</option>
                    {rooms.map(room => (
                        <option key={room._id} value={room._id}>{room.name}</option>
                    ))}
                </select>

                <button type="submit">Добавить</button>
            </form>

            {/* ✅ Вывод списка временных интервалов */}
            <h3>Актуальные временные интервалы:</h3>
            {periods.length > 0 ? (
                <ul>
                    {periods.map(period => (
                        <li key={period._id}>
                            {period.name}: {period.startTime} - {period.endTime} (День: {weekDays.find(d => d.id === period.dayOfWeek)?.name || "Не задано"}, Кабинет: {period.room || "Не задано"})
                        </li>
                    ))}
                </ul>
            ) : (
                <p>Нет доступных временных интервалов.</p>
            )}
        </div>
    );
};

export default CreatePeriod;
